def S(N):
    total_sum = 0
    for a in range(1, N + 1):
        for b in range(1, N + 1):
            total_sum += int((a * b) / (N + 1))
    return total_sum

def check_condition(N, S_N):
    required = (N**3 - N**2 + 2) / 4
    return S_N == required, required

N_values = [1, 2, 3, 4]
results = {}
print("--- Results ---")
for N in N_values:
    s_n = S(N)
    holds, required = check_condition(N, s_n)
    results[N] = {
        "S(N)": s_n,
        "Target": required,
        "Holds": holds
    }
    print(f"N={N}: S(N) = {results[N]['S(N)']}. Target = {results[N]['Target']}. Holds? {results[N]['Holds']}")

print("\n--- Dictionary Format ---")
import pprint
pprint.pprint(results)
